<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute, useRouter } from 'vue-router';
import api from 'dashboard/api/knowledgeBases';
import Button from 'dashboard/components-next/button/Button.vue';
import Dialog from 'dashboard/components-next/dialog/Dialog.vue';
import Input from 'dashboard/components-next/input/Input.vue';
import Switch from 'dashboard/components-next/switch/Switch.vue';
import TextArea from 'dashboard/components-next/textarea/TextArea.vue';

const { t, locale } = useI18n();
const route = useRoute();
const router = useRouter();
const defaults = { name: '', description: '', active: true, similarity_threshold: 0.35, retrieval_top_k: 5, chunk_size: 2400, chunk_overlap: 240 };
const form = ref({ ...defaults });
const documents = ref([]); const pendingFiles = ref([]); const pendingTexts = ref([]); const fileInput = ref(null); const query = ref(''); const candidates = ref(null); const error = ref(''); const busy = ref(false); const loading = ref(true); const progress = ref(''); const uploadResults = ref([]); const partialBaseId = ref(null); const documentDialog = ref(null); const viewDialog = ref(null); const extracted = ref(null); const documentDraft = ref({ name: '', content: '', file: null }); let timer;
const isEdit = computed(() => Boolean(route.params.knowledgeBaseId));
const changedChunking = computed(() => isEdit.value && (Number(form.value.chunk_size) !== Number(form.value._initial_chunk_size) || Number(form.value.chunk_overlap) !== Number(form.value._initial_chunk_overlap)));
const date = value => new Date(value).toLocaleString(locale.value.replace('_', '-'));
const report = failure => { const code = failure.response?.data?.error; error.value = t(['invalid_file', 'document_limit'].includes(code) ? `KNOWLEDGE.ERRORS.${code}` : 'KNOWLEDGE.ERROR'); };
const loadDocuments = async () => { if (isEdit.value) documents.value = (await api.documents(route.params.knowledgeBaseId)).data.documents; };
const load = async () => { try { if (isEdit.value) { const data = (await api.show(route.params.knowledgeBaseId)).data; form.value = { ...defaults, ...data, similarity_threshold: data.similarity_threshold ?? data.effective_similarity_threshold, retrieval_top_k: data.retrieval_top_k ?? data.effective_retrieval_top_k, chunk_size: data.chunk_size ?? data.effective_chunk_size, chunk_overlap: data.chunk_overlap ?? data.effective_chunk_overlap, _initial_chunk_size: data.effective_chunk_size, _initial_chunk_overlap: data.effective_chunk_overlap }; await loadDocuments(); } } catch (failure) { report(failure); } finally { loading.value = false; } };
const run = async action => { if (busy.value) return; busy.value = true; error.value = ''; try { await action(); } catch (failure) { report(failure); } finally { busy.value = false; } };
const save = () => run(async () => { const { id, name, description, active, similarity_threshold, retrieval_top_k, chunk_size, chunk_overlap } = form.value; const knowledge_base = { name, description, active, similarity_threshold, retrieval_top_k, chunk_size, chunk_overlap }; const createdNow = !id || Boolean(partialBaseId.value); const response = id ? await api.update(id, { knowledge_base }) : await api.create({ knowledge_base }); const baseId = id || response.data.id; form.value.id = baseId; partialBaseId.value = baseId; const items = [...pendingFiles.value.map(file => ({ kind: 'file', value: file, status: 'pending' })), ...pendingTexts.value.map(text => ({ kind: 'text', value: text, status: 'pending' }))]; for (let index = 0; index < items.length; index += 1) { const item = items[index]; if (item.status === 'success') continue; item.status = 'uploading'; progress.value = t('KNOWLEDGE.UPLOAD_PROGRESS', { current: index + 1, total: items.length }); try { if (item.kind === 'file') { const data = new FormData(); data.append('document[name]', item.value.name.replace(/\.[^.]+$/, '')); data.append('document[file]', item.value); await api.saveDocument(baseId, data); } else await api.saveDocument(baseId, { document: item.value }); item.status = 'success'; } catch { const existing = createdNow ? (await api.documents(baseId)).data.documents : []; const itemName = item.kind === 'file' ? item.value.name.replace(/\.[^.]+$/, '') : item.value.name; item.status = existing.some(document => document.name === itemName) ? 'success' : 'failed'; } } uploadResults.value = items; const failed = items.filter(item => item.status === 'failed'); if (failed.length) { error.value = t('KNOWLEDGE.PARTIAL_UPLOAD', { failed: failed.length, total: items.length }); pendingFiles.value = items.filter(item => item.status === 'failed' && item.kind === 'file').map(item => item.value); pendingTexts.value = items.filter(item => item.status === 'failed' && item.kind === 'text').map(item => item.value); await loadDocuments(); return; } pendingFiles.value = []; pendingTexts.value = []; progress.value = ''; uploadResults.value = []; router.push({ name: 'knowledge_base_edit', params: { knowledgeBaseId: baseId } }); });
const selectFiles = event => { pendingFiles.value.push(...Array.from(event.target.files)); event.target.value = ''; }; const chooseFiles = () => fileInput.value?.click();
const removePending = file => { pendingFiles.value = pendingFiles.value.filter(item => item !== file); };
const retryFailed = () => save();
const newDocument = () => { documentDraft.value = { name: '', content: '', file: null }; documentDialog.value.open(); };
const openDocument = document => run(async () => { const data = (await api.document(route.params.knowledgeBaseId, document.id)).data; documentDraft.value = { id: data.id, name: data.name, content: data.source_type === 'manual' ? data.content : '', file: null }; documentDialog.value.open(); });
const saveDocument = () => run(async () => { const draft = documentDraft.value; if (!isEdit.value && !draft.id) { pendingTexts.value.push({ name: draft.name, content: draft.content }); documentDialog.value.close(); return; } let payload; if (draft.file) { payload = new FormData(); payload.append('document[name]', draft.name); payload.append('document[file]', draft.file); } else payload = { document: { name: draft.name, content: draft.content } }; await api.saveDocument(route.params.knowledgeBaseId, payload, draft.id); documentDialog.value.close(); await loadDocuments(); });
const removeDocument = document => run(async () => { await api.deleteDocument(route.params.knowledgeBaseId, document.id); await loadDocuments(); });
const reindex = document => run(async () => { await api.reindex(route.params.knowledgeBaseId, document.id); await loadDocuments(); });
const view = document => run(async () => { extracted.value = (await api.document(route.params.knowledgeBaseId, document.id)).data; viewDialog.value.open(); });
const search = () => run(async () => { candidates.value = (await api.search(route.params.knowledgeBaseId, query.value)).data.candidates || []; });
onMounted(() => { load(); timer = setInterval(() => { if (!document.hidden && !busy.value && documents.value.some(item => item.status === 'processing')) run(loadDocuments); }, 15000); });
onUnmounted(() => clearInterval(timer));
</script>

<template>
  <main class="flex flex-col w-full max-w-5xl gap-6 mx-auto pb-8">
    <header class="flex flex-wrap items-center justify-between gap-4"><div><Button variant="ghost" :label="t('KNOWLEDGE.BACK')" @click="router.push({ name: 'knowledge_bases_settings' })" /><h1 class="mt-2 text-xl font-semibold text-n-slate-12">{{ isEdit ? t('KNOWLEDGE.EDIT_TITLE') : t('KNOWLEDGE.CREATE_TITLE') }}</h1><p class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.PAGE_HELP') }}</p></div><div class="flex gap-2"><Button variant="faded" :label="t('KNOWLEDGE.CANCEL')" :disabled="busy" @click="router.push({ name: 'knowledge_bases_settings' })" /><Button :label="t('KNOWLEDGE.SAVE')" :disabled="loading || busy || !form.name.trim()" @click="save" /></div></header>
    <p v-if="progress" class="text-sm text-n-slate-11">{{ progress }}</p><div v-if="uploadResults.length" class="flex flex-col gap-1 p-3 rounded-lg bg-n-solid-2"><p v-for="item in uploadResults" :key="item.kind + item.value.name" class="text-sm" :class="item.status === 'success' ? 'text-n-teal-11' : 'text-n-ruby-11'">{{ item.status === 'success' ? '✓' : '✕' }} {{ item.kind === 'file' ? item.value.name : item.value.name }}</p></div><p v-if="error" role="alert" class="text-sm text-n-ruby-11">{{ error }}</p><Button v-if="partialBaseId && error" variant="faded" :label="t('KNOWLEDGE.RETRY_FAILED')" :disabled="busy" @click="retryFailed" />
    <section class="flex flex-col gap-4 p-5 rounded-xl bg-n-solid-2"><h2 class="font-medium text-n-slate-12">{{ t('KNOWLEDGE.GENERAL') }}</h2><Input v-model="form.name" :label="t('KNOWLEDGE.NAME')" :max-length="100" /><TextArea v-model="form.description" :label="t('KNOWLEDGE.DESCRIPTION')" :max-length="2000" :auto-height="true" /><label class="flex items-center justify-between text-sm text-n-slate-12">{{ t('KNOWLEDGE.ACTIVE') }}<Switch v-model="form.active" /></label></section>
    <section class="flex flex-col gap-4 p-5 rounded-xl bg-n-solid-2"><div><h2 class="font-medium text-n-slate-12">{{ t('KNOWLEDGE.RETRIEVAL') }}</h2><p class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.RETRIEVAL_HELP') }}</p></div><div class="grid grid-cols-1 gap-4 md:grid-cols-2"><Input v-model.number="form.similarity_threshold" type="number" min="0" max="1" step="0.01" :label="t('KNOWLEDGE.THRESHOLD')" :message="t('KNOWLEDGE.THRESHOLD_HELP')" /><Input v-model.number="form.retrieval_top_k" type="number" min="1" max="10" :label="t('KNOWLEDGE.TOP_K')" :message="t('KNOWLEDGE.TOP_K_HELP')" /></div></section>
    <section class="flex flex-col gap-4 p-5 rounded-xl bg-n-solid-2"><h2 class="font-medium text-n-slate-12">{{ t('KNOWLEDGE.PROCESSING') }}</h2><p class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.PROCESSING_HELP') }}</p><div class="grid grid-cols-1 gap-4 md:grid-cols-2"><Input v-model.number="form.chunk_size" type="number" min="400" max="10000" :label="t('KNOWLEDGE.CHUNK_SIZE')" /><Input v-model.number="form.chunk_overlap" type="number" min="0" :label="t('KNOWLEDGE.CHUNK_OVERLAP')" /></div><p v-if="changedChunking" class="text-sm text-n-amber-11">{{ t('KNOWLEDGE.REINDEX_WARNING') }}</p><p class="text-xs text-n-slate-11">{{ t('KNOWLEDGE.EMBEDDING_MODEL') }}</p></section>
    <section class="flex flex-col gap-4 p-5 rounded-xl bg-n-solid-2"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-medium text-n-slate-12">{{ t('KNOWLEDGE.DOCUMENTS') }}</h2><p class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.UPLOAD_HELP') }}</p></div><div class="flex gap-2"><input ref="fileInput" type="file" multiple accept=".txt,.md,.pdf,text/plain,text/markdown,application/pdf" class="hidden" @change="selectFiles" /><Button variant="faded" :label="t('KNOWLEDGE.ADD_FILE')" @click="chooseFiles" /><Button variant="faded" :label="t('KNOWLEDGE.ADD_TEXT')" @click="newDocument" /></div></div><div v-if="pendingFiles.length" class="flex flex-col gap-2"><div v-for="file in pendingFiles" :key="file.name + file.lastModified" class="flex items-center justify-between gap-2 p-2 rounded-lg bg-n-solid-1"><span class="text-sm text-n-slate-12 truncate">{{ file.name }}</span><Button variant="ghost" color="ruby" :label="t('KNOWLEDGE.REMOVE')" @click="removePending(file)" /></div></div><p v-if="isEdit && !documents.length" class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.NO_DOCUMENTS') }}</p><article v-for="item in documents" :key="item.id" class="flex flex-wrap items-center justify-between gap-3 p-3 rounded-lg bg-n-solid-1"><div><strong class="text-sm text-n-slate-12 break-words">{{ item.name }}</strong><p class="text-xs text-n-slate-11">{{ item.source_type }} · {{ t(`KNOWLEDGE.STATUS.${item.status}`) }} · {{ t('KNOWLEDGE.CHUNKS', { count: item.chunks_count }) }} · {{ date(item.updated_at) }}</p></div><div class="flex flex-wrap gap-2"><Button variant="ghost" :label="t('KNOWLEDGE.VIEW')" @click="view(item)" /><Button variant="ghost" :label="t('KNOWLEDGE.EDIT')" @click="openDocument(item)" /><Button variant="ghost" :label="t('KNOWLEDGE.REINDEX')" :disabled="item.status === 'processing'" @click="reindex(item)" /><Button variant="ghost" color="ruby" :label="t('KNOWLEDGE.DELETE')" @click="removeDocument(item)" /></div></article></section>
    <section v-if="isEdit" class="flex flex-col gap-4 p-5 rounded-xl bg-n-solid-2"><h2 class="font-medium text-n-slate-12">{{ t('KNOWLEDGE.SEARCH_TEST') }}</h2><form class="flex flex-wrap gap-2" @submit.prevent="search"><Input v-model="query" class="flex-1" :placeholder="t('KNOWLEDGE.SEARCH_QUESTION')" /><Button type="submit" :label="t('KNOWLEDGE.SEARCH')" :disabled="busy || !query.trim()" /></form><p v-if="candidates && !candidates.length" class="text-sm text-n-slate-11">{{ t('KNOWLEDGE.NO_RESULTS') }}</p><article v-for="candidate in candidates" :key="candidate.id" class="p-3 rounded-lg bg-n-solid-1"><div class="flex flex-wrap justify-between gap-2 text-xs text-n-slate-11"><span>{{ candidate.document }} · {{ t(candidate.accepted ? 'KNOWLEDGE.ACCEPTED' : 'KNOWLEDGE.REJECTED') }}</span><span>{{ candidate.score }} · {{ t('KNOWLEDGE.THRESHOLD_VALUE', { value: candidate.threshold }) }}</span></div><p class="mt-2 text-sm whitespace-pre-wrap break-words text-n-slate-12">{{ candidate.content }}</p></article></section>
    <Dialog ref="documentDialog" width="2xl" :title="t('KNOWLEDGE.DOCUMENT_EDITOR')" :confirm-button-label="t('KNOWLEDGE.SAVE')" :disable-confirm-button="busy || !documentDraft.name.trim() || (!documentDraft.file && !documentDraft.content.trim())" @confirm="saveDocument"><div class="flex flex-col gap-4"><Input v-model="documentDraft.name" :label="t('KNOWLEDGE.NAME')" /><input type="file" accept=".txt,.md,.pdf,text/plain,text/markdown,application/pdf" @change="documentDraft.file = $event.target.files[0]" /><TextArea v-if="!documentDraft.file" v-model="documentDraft.content" :label="t('KNOWLEDGE.MANUAL_TEXT')" :max-length="500000" :auto-height="true" /></div></Dialog>
    <Dialog ref="viewDialog" width="2xl" :title="extracted?.name" :show-confirm-button="false" :cancel-button-label="t('KNOWLEDGE.CLOSE')"><pre class="max-h-96 overflow-y-auto whitespace-pre-wrap break-words text-sm text-n-slate-12">{{ extracted?.content || t('KNOWLEDGE.NO_EXTRACTED_TEXT') }}</pre></Dialog>
  </main>
</template>
